INSERT INTO `appscheduler_bookings` (`id`, `uuid`, `calendar_id`, `booking_price`, `booking_total`, `booking_deposit`, `booking_tax`, `booking_status`, `payment_method`, `c_name`, `c_email`, `c_phone`, `c_country_id`, `c_city`, `c_state`, `c_zip`, `c_address_1`, `c_address_2`, `c_notes`, `cc_type`, `cc_num`, `cc_exp_year`, `cc_exp_month`, `cc_code`, `txn_id`, `processed_on`, `created`, `locale_id`, `ip`) VALUES('2309', 'XM1737105518', '1', '100.00', '100.00', '100.00', '0.00', 'confirmed', 'invoice', 'Büro - Constanze Müllner / Gabriel Laimer bringt PC Diag', 'constanze.muellner@gmx.at', '+436769408744', '15', 'Wien', NULL, '1130', 'Fourniergasse 4-6', '7', 'Liebes Team, rnich habe ein Problem mit meiner Mail App (bisher Mail jetzt Outlook new); seit Wechsel Passwort auf GMX komme ich weder in den alten Mailserver rein noch kann ich das neue Outlook installieren.rnAußerdem scheint es ein Problem mit den Microsoft Konten (Büro und privat) zu geben.rn2. Thema, das mich interessiert, ist warum meine WLAN Verbindung nicht mehr automatisch funktioniert, obwohl das W-LAN eingestellt ist. Ich muss den Router immer ein - und ausschalten bevor die Verbindung steht, obwohl der Router neu ist und auch der Internetvertrag neu und schneller. Ich nehme an, es liegt am Laptop??? Dazu hätte ich bitte auch gern eine Bestätigung bzw. Hilfe. Der Laptop gibt nämlich oft auch keinen Ton im Youtube. Dazu muss ich herunterfahren und erst dann kommt wieder der Ton.  Danke für den Termin! lg Constanze MüllnerrnrnGabriel Laimer Diag: 0676-4260227', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2025-01-17 10:18:38', '2', '178.165.197.244');
