INSERT INTO `appscheduler_plugin_base_multi_lang` (`id`, `foreign_id`, `model`, `locale`, `field`, `content`, `source`) VALUES('1595', '1', 'pjCalendar', '1', 'confirm_tokens_client', '<p>Hello {Name},<br /><br />You have just made an appointment on www.telesupport.at. The details of your booking can be found in the following overview:<br /><br />Personal details:<br />Name: {Name}<br />Email: {Email}<br />Phone: {Phone}<br />Address: {Address1} / {Address2}<br />City: {City}<br />ZIP: {Zip}<br />Additional notes: {Notes}<br /><br />Booking details:<br />Booking-ID: {BookingID}<br />Services: {Services}<br />Total: {Total}<br /><br />If you want to cancel your booking, please click on this link:<br />&gt; {CancelURL}<br /><br />Here you can download the remote support module:<br />&gt; https://telesupport.at/down/fernwartung.exe<br /><br />If you have any questions or need more information, please contact us by phone at 0660.8173757 or by email at info@telesupport.at.<br /><br />Many Thanks!<br /><br />Your telesupport team</p><p>&nbsp;</p>', 'data');
