INSERT INTO `appscheduler_plugin_base_multi_lang` (`id`, `foreign_id`, `model`, `locale`, `field`, `content`, `source`) VALUES('3912', '1', 'pjCalendar', '2', 'confirm_subject_client', 'telesupport.at - Bestätigung Terminbuchung', 'script');
INSERT INTO `appscheduler_plugin_base_multi_lang` (`id`, `foreign_id`, `model`, `locale`, `field`, `content`, `source`) VALUES('3913', '1', 'pjCalendar', '2', 'confirm_tokens_client', '<p>Hallo {Name},</p><p>Sie haben soeben eine Terminbuchung auf www.telesupport.at erfolgreich durchgef&uuml;hrt.</p><p>Sollten Sie die Buchung mit PayPal als Zahlungsoption get&auml;tigt haben, erhalten Sie nach Best&auml;tigung des Zahlungseinganges eine gesonderte Zahlungsbest&auml;tigung per Mail. Die Buchung wird dann in unserem Terminvergabesystem automatisch aktiviert.</p><p>Falls die Zahlung aus irgendeinem Grund nicht ausgef&uuml;hrt werden kann oder der Zahlungsvorgang vor Abschluss unterbrochen wurde, wird die Buchung im Terminkalender nach 15 Minuten gel&ouml;scht.</p><p>Die Details zu Ihrer Buchung finden Sie in der nachfolgenden &Uuml;bersicht:<br /><br />Pers&ouml;nliche Information:<br />Name: {Name}<br />E-Mail: {Email}<br />Telefon: {Phone}<br />Adresse: {Address1} / {Address2}<br />Stadt: {City}<br />PLZ: {Zip}<br />Bemerkung: {Notes}<br /><br />Buchungsinformation:<br />Buchungsnummer: {BookingID}<br />Services: {Services}<br />Gesamt: {Total}<br /><br />Wenn Sie Ihre Buchung l&ouml;schen wollen, klicken Sie bitte auf diesen Link:<br />&gt; {CancelURL}<br /><br />Hier k&ouml;nnen Sie das Fernwartungsmodul herunterladen:<br />&gt; https://telesupport.at/down/fernwartung.exe<br /><br />Sollten Sie Fragen haben oder weitere Informationen ben&ouml;tigen, kontaktieren Sie uns bitte unter der Rufnummer 0660.8173757 oder per Mail unter info@telesupport.at.<br /><br />Vielen Dank!<br /><br />Ihr telesupport Team</p><p>&nbsp;</p>', 'script');
INSERT INTO `appscheduler_plugin_base_multi_lang` (`id`, `foreign_id`, `model`, `locale`, `field`, `content`, `source`) VALUES('3914', '1', 'pjCalendar', '2', 'payment_subject_client', 'telesupport.at - Bestätigung Zahlung', 'script');
INSERT INTO `appscheduler_plugin_base_multi_lang` (`id`, `foreign_id`, `model`, `locale`, `field`, `content`, `source`) VALUES('3915', '1', 'pjCalendar', '2', 'payment_tokens_client', '<p>Wir haben die Zahlung f&uuml;r Ihre Buchung erhalten und diese ist nun best&auml;tigt.<br /><br />Buchungsnummer: {BookingID}<br /><br /><br />Vielen Dank!<br /><br />Ihr telesupport Team</p>', 'script');
INSERT INTO `appscheduler_plugin_base_multi_lang` (`id`, `foreign_id`, `model`, `locale`, `field`, `content`, `source`) VALUES('3916', '1', 'pjCalendar', '2', 'confirm_subject_admin', 'New booking received', 'script');
INSERT INTO `appscheduler_plugin_base_multi_lang` (`id`, `foreign_id`, `model`, `locale`, `field`, `content`, `source`) VALUES('3917', '1', 'pjCalendar', '2', 'confirm_tokens_admin', 'New booking has been made. <br/><br/>ID: {BookingID}<br/><br/>Services<br/>{Services}<br/><br/>Personal details<br/>Name: {Name}<br/>Phone: {Phone}<br/>Email: {Email}<br/><br/>Price<br/>Tax: {Price}<br/>Tax: {Tax}<br/>Total: {Total}<br/>Deposit required to confirm the booking: {Deposit}<br/><br/>Additional notes:<br/>{Notes}', 'script');
